def solve(n, edges):
    # Initialize each node as its own parent
    parent = list(range(n))

    # Find the root parent of a node with path compression
    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    # Union function to merge two sets
    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    # Process each edge to perform union
    for u, v in edges:
        union(u, v)

    # Count the number of unique roots (connected components)
    roots = set()
    for i in range(n):
        roots.add(find(i))

    return len(roots)

