class PriorityQueue:
    def __init__(self):
        self.heap = []
        self.count = 0

    def push(self, item, priority):
        heapq.heappush(self.heap, (priority, item))
        self.count += 1

    def pop(self):
        if self.count == 0:
            return None
        self.count -= 1
        return heapq.heappop(self.heap)[1]

    def is_empty(self):
        return self.count == 0

