def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import defaultdict

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Memoization cache: key = node, value = shortest distance from s to this node
    min_distances = {node: float('inf') for node in range(n)}
    min_distances[s] = 0

    # Use a stack for DFS
    stack = [(s, 0)]  # (node, current_distance)
    reached_t = False
    shortest_distance = float('inf')

    while stack:
        node, dist = stack.pop()

        if node == t:
            shortest_distance = min(shortest_distance, dist)
            reached_t = True
            continue

        if dist > min_distances[node]:
            continue  # A better path already exists to this node

        # Explore all edges from the current node
        for neighbor, weight in graph[node]:
            new_dist = dist + weight
            if new_dist < min_distances[neighbor]:
                min_distances[neighbor] = new_dist
                stack.append((neighbor, new_dist))

    return shortest_distance if reached_t else -1

